const mpgData = await browserjs(tabId, async () => {
  try {
    const res = await fetch("/Trucks/15ft-Moving-Truck-Rental/DC/");
    const html = await res.text();
    // parse DOM
    const parser = new DOMParser();
    const doc = parser.parseFromString(html, "text/html");
    const text = doc.body.innerText;
    const matches = [];
    const lines = text.split('\n');
    for (const l of lines) {
      if (l.toLowerCase().includes('mpg') || l.toLowerCase().includes('fuel') || l.toLowerCase().includes('gallon')) {
        matches.push(l.trim());
      }
    }
    return { status: res.status, matches: matches.slice(0, 20) };
  } catch (e) {
    return { error: e.message };
  }
});
console.log("U-Haul 15ft truck MPG data:", JSON.stringify(mpgData, null, 2));
